import os,re,collections
root='.'
edges=collections.defaultdict(set)
rev=collections.defaultdict(set)
files=[]
for d,_,fs in os.walk('.'):
    if '/test' in d or d.startswith('./test'): continue
    for f in fs:
        if f.endswith('.mjs'):
            p=os.path.normpath(os.path.join(d,f)); files.append(p)
for p in files:
    src=open(p).read()
    for m in re.finditer(r"from\s+'([^']+)'",src):
        t=m.group(1)
        if t.startswith('.'):
            tp=os.path.normpath(os.path.join(os.path.dirname(p),t))
            edges[p].add(tp); rev[tp].add(p)
        elif t.startswith('#') or '/' in t and not t.startswith('node:'):
            edges[p].add('EXT:'+t)
for p in sorted(files):
    ins=sorted(x for x in rev[p])
    print(f"{p}  <-in {len(ins)}")
    for i in ins: print("      ",i)
EOF

